import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    for _ in range(t):
        sys.stdin.readline()  # Skip the empty line
        n, k = read_ints()
        edges = [read_ints() for _ in range(n - 1)]

        # Create adjacency list for the tree
        tree = defaultdict(list)
        degree = [0] * (n + 1)
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)
            degree[u] += 1
            degree[v] += 1

        # Initialize the queue with leaves
        queue = deque()
        for i in range(1, n + 1):
            if degree[i] == 1:
                queue.append(i)

        # Perform k operations
        for _ in range(k):
            if len(queue) == 0:
                break
            new_queue = deque()
            while queue:
                leaf = queue.popleft()
                for neighbor in tree[leaf]:
                    degree[neighbor] -= 1
                    if degree[neighbor] == 1:
                        new_queue.append(neighbor)
            queue = new_queue

        # The remaining vertices are the ones that are not leaves
        remaining_vertices = n - len(queue)
        print(remaining_vertices)

if __name__ == "__main__":
